[
  {
    "hindi": "त्व सहित व्यवस्था",
    "hinglish": "tva sahit vyavastha",
    "pageno": 83,
    "paribhasha": [
      "मानवीयता पूर्ण आचरण सहित सार्वभौम व्यवस्था में भागीदारी।",
      "प्रत्येक एक में धर्म एवं स्वभाव सहज प्रकाशन।"
    ]
  },
  {
    "hindi": "न्यायपूर्ण व्यवस्था",
    "hinglish": "nyaypurn vyavastha",
    "pageno": 104,
    "paribhasha": [
      "मानवीयता के संरक्षण एवं संवर्धन के लिए नैतिकता पूर्वक चारों आयामों एवं पाँचो स्थितियों में निर्विषमता तथा सभ्यता, संस्कृति, विधि, व्यवस्था की एकात्मता।",
      "चार आयाम - विचार, व्यवहार, व्यवसाय, अनुभव। पाँच स्थिति - व्यक्ति, परिवार, समाज, राष्ट्र, अंतर्राष्ट्र।"
    ]
  },
  {
    "hindi": "परिवार मूलक स्वराज्य व्यवस्था",
    "hinglish": "parivar mulak svarajya vyavastha",
    "pageno": 112,
    "paribhasha": [
      "जागृत मानव परिवार में कम से कम दस व्यक्तियों का होना स्वीकार होता है। ऐसे परिवार में से एक व्यक्ति को व्यवस्था के लोकव्यापीकरण करने के उद्देश्य से दस व्यक्ति निर्वाचित करते हैं स्वयं भी अपने को निर्वाचित कर लेता है इस प्रकार दस व्यक्तियों में से एक व्यक्ति व्यवस्था में भागीदारी करने के लिए तैयारी करता है। यही प्रथम जन प्रतिनिधि सभा है। इसी प्रकार से पूरे गाँव में, पूरे देश में, पूरे विश्व में मानवीय शिक्षा संस्कारपूर्वक जागृति के लिए वांछित ज्ञान विवेक विज्ञान सहज संस्कार स्थापित किया जाना होता है।"
    ]
  },
  {
    "hindi": "राज्य व्यवस्था",
    "hinglish": "rajya vyavastha",
    "pageno": 160,
    "paribhasha": [
      "परिवार मूलक स्वराज्य विधि सहित सार्वभौम व्यवस्था सहज वैभव।"
    ]
  },
  {
    "hindi": "व्यवस्था",
    "hinglish": "vyavastha",
    "pageno": 179,
    "paribhasha": [
      "मानवत्व सहित वर्तमान परंपरा, वर्तमान में स्थिरता निश्चयता निरंतरता, सार्वभौम व्यवस्था परिवार मूलक दश सोपानीय व्यवस्था में भागीदारी, वर्तमान में विश्वास।",
      "मानवीय आचरण, संस्कृति एवं सभ्यता पूर्ण व्यवहार परंपरा वर्तमान में होना रहना।",
      "विधि के आशय को कार्यरूप में प्रदान करने हेतु प्रस्तुत परम्परा ही व्यवस्था है।",
      "व्यवहार गति में स्थायित्व, निरंतरता और वर्तमान में विश्वास।"
    ]
  },
  {
    "hindi": "व्यवस्थागत",
    "hinglish": "vyavasthagat",
    "pageno": 179,
    "paribhasha": [
      "व्यवस्था व्यवहार सुलभ होने के रूप में व्यवस्था मर्यादा में, व्यवस्थापूर्वक नियम, नियंत्रण, संतुलन रूप में।"
    ]
  },
  {
    "hindi": "व्यवस्था भेद",
    "hinglish": "vyavastha bhed",
    "pageno": 179,
    "paribhasha": [
      "दश सोपानीय विधि सहज।"
    ]
  },
  {
    "hindi": "व्यवहार व्यवस्था",
    "hinglish": "vyavahar vyavastha",
    "pageno": 180,
    "paribhasha": [
      "सार्वभौम व्यवस्था।"
    ]
  },
  {
    "hindi": "समग्र व्यवस्था",
    "hinglish": "samagra vyavastha",
    "pageno": 186,
    "paribhasha": [
      "जड़-चैतन्य प्रकृति में, से, के लिए समग्र व्यवस्था।"
    ]
  },
  {
    "hindi": "सम्यक व्यवस्था",
    "hinglish": "samyak vyavastha",
    "pageno": 192,
    "paribhasha": [
      "पूर्णता के अर्थ में की गई व्यवस्था, क्रिया पूर्णता, आचरण पूर्णता।"
    ]
  }
]
